class Solution {
public:
    string rankTeams(vector<string>& votes) {
        int V = votes.size();
        int L = votes[0].size();                 // number of teams
        unordered_map<char, vector<int>> cnt;   // team -> counts per position

        // initialise count vectors
        for (char c : votes[0]) cnt[c] = vector<int>(L, 0);

        // fill counts
        for (const string& v : votes) {
            for (int p = 0; p < L; ++p) {
                cnt[v[p]][p]++;                 // team v[p] got a vote for position p
            }
        }

        // list of teams
        vector<char> teams;
        teams.reserve(L);
        for (char c : votes[0]) teams.push_back(c);

        // custom sort
        auto comp = [&](char a, char b) {
            const vector<int>& ca = cnt[a];
            const vector<int>& cb = cnt[b];
            for (int p = 0; p < L; ++p) {
                if (ca[p] != cb[p]) return ca[p] > cb[p]; // more votes in higher rank wins
            }
            return a < b;                                 // alphabetical tie‑breaker
        };
        sort(teams.begin(), teams.end(), comp);

        // build result string
        string res;
        res.reserve(L);
        for (char c : teams) res.push_back(c);
        return res;
    }
};

