import java.util.*;

class Solution {
    public String rankTeams(String[] votes) {
        int V = votes.length;
        int L = votes[0].length();                 // number of teams

        // team -> counts per position
        Map<Character, int[]> cnt = new HashMap<>();

        // initialise count arrays
        for (char c : votes[0].toCharArray()) {
            cnt.put(c, new int[L]);
        }

        // fill counts
        for (String v : votes) {
            char[] arr = v.toCharArray();
            for (int p = 0; p < L; ++p) {
                cnt.get(arr[p])[p]++;             // team arr[p] got a vote for position p
            }
        }

        // list of teams
        List<Character> teams = new ArrayList<>(L);
        for (char c : votes[0].toCharArray()) {
            teams.add(c);
        }

        // custom sort
        Collections.sort(teams, new Comparator<Character>() {
            @Override
            public int compare(Character a, Character b) {
                int[] ca = cnt.get(a);
                int[] cb = cnt.get(b);
                for (int p = 0; p < L; ++p) {
                    if (ca[p] != cb[p]) {
                        return ca[p] > cb[p] ? -1 : 1; // more votes in higher rank wins
                    }
                }
                return a < b ? -1 : 1;                 // alphabetical tie‑breaker
            }
        });

        // build result string
        StringBuilder res = new StringBuilder(L);
        for (char c : teams) {
            res.append(c);
        }
        return res.toString();
    }
}

