class Solution:
    def rankTeams(self, votes: list[str]) -> str:
        V = len(votes)
        L = len(votes[0])                     # number of teams

        # team -> counts per position
        cnt: dict[str, list[int]] = {}
        for c in votes[0]:
            cnt[c] = [0] * L

        # fill counts
        for v in votes:
            for p, c in enumerate(v):
                cnt[c][p] += 1

        # list of teams
        teams = list(votes[0])

        # custom sort: more votes in higher rank wins, then alphabetical
        def comp(a: str, b: str) -> bool:
            ca, cb = cnt[a], cnt[b]
            for p in range(L):
                if ca[p] != cb[p]:
                    return ca[p] > cb[p]
            return a < b

        # Python's sorted doesn't accept cmp, so we use key that mimics the comparison
        teams.sort(key=lambda x: tuple(-cnt[x][p] for p in range(L)) + (x,))

        # build result string
        return "".join(teams)

