/**
 * @param {string[]} votes
 * @return {string}
 */
var rankTeams = function(votes) {
    const V = votes.length;
    const L = votes[0].length; // number of teams

    // team -> counts per position
    const cnt = new Map();

    // initialise count vectors
    for (const c of votes[0]) {
        cnt.set(c, new Array(L).fill(0));
    }

    // fill counts
    for (const v of votes) {
        for (let p = 0; p < L; ++p) {
            const team = v[p];
            cnt.get(team)[p]++; // team v[p] got a vote for position p
        }
    }

    // list of teams
    const teams = [];
    for (const c of votes[0]) teams.push(c);

    // custom sort
    teams.sort((a, b) => {
        const ca = cnt.get(a);
        const cb = cnt.get(b);
        for (let p = 0; p < L; ++p) {
            if (ca[p] !== cb[p]) return ca[p] > cb[p] ? -1 : 1; // more votes in higher rank wins
        }
        return a < b ? -1 : 1; // alphabetical tie‑breaker
    });

    // build result string
    return teams.join('');
};
